// 風險：UI執行緒同步阻塞
var result = LoadAsync().Result;
// 常見方向：事件handler本身非同步等待
async void OnClick(object? sender, EventArgs e) {
    try { var result = await LoadAsync(); UpdateView(result); }
    catch (Exception error) { ShowFailure(error); }
}
// async void僅用於契約要求void的事件邊界，內部工作仍返回Task。
